//! AMG benchmark suite — Step 8.5a Phase 0.
//!
//! Phase 0 scope: Jacobi-CG reference only across 9 cases (3 Poisson
//! synthetic, 6 Stokes snapshots from `bench_data/`). Phase 2+ adds
//! the AmgCG path side-by-side.
//!
//! Run with:
//! ```bash
//! cargo bench -p ymir-core --bench amg_benchmark
//! ```
//!
//! Poisson synthetic cases are constructed on-demand from a seeded
//! PRNG so no serialised data is required. Stokes snapshots are
//! generated by `gen_bench_data` and loaded at setup; missing
//! snapshots trigger a skip with an explanatory message rather than
//! a hard failure so a partial benchmark run is possible.
//!
//! CG iteration counts are the primary AMG gate metric. Criterion
//! reports wallclock and variance natively; each case runs at ≥ 5
//! samples by default. The first call of each case logs the
//! iteration count to stderr for the report.

use std::path::PathBuf;

use criterion::{criterion_group, criterion_main, BatchSize, Criterion};

use ymir_core::tectonics_v2::field::Field2D;
use ymir_core::tectonics_v2::stokes::nullspace;
use ymir_core::tectonics_v2::stokes::operator::{
    apply_momentum, apply_tangent, StokesGrid, TangentContext,
};
use ymir_core::tectonics_v2::stokes::precond::VelocityJacobi;
use ymir_core::tectonics_v2::stokes::snapshot::{field_from_vec, LinearStokesSnapshot};
use ymir_core::tectonics_v2::stokes::solver::{ConjugateGradient, LinearSolver, SolverStats};

// ---------------------------------------------------------------------------
// Poisson synthetic cases
// ---------------------------------------------------------------------------

/// Cell-centred Poisson case with 5-pt Laplacian operator `-∇·(η ∇u)`.
struct PoissonCase {
    nx: usize,
    ny: usize,
    dx: f64,
    dy: f64,
    eta: Vec<f64>, // cell-centre viscosity/coefficient
    rhs: Vec<f64>, // cell-centred, mean-subtracted
}

fn poisson_constant(n: usize) -> PoissonCase {
    let dx = 1.0 / n as f64;
    let dy = dx;
    let eta = vec![1.0; n * n];
    let mut rhs = vec![0.0; n * n];
    for j in 0..n {
        for i in 0..n {
            let x = (i as f64 + 0.5) * dx;
            let y = (j as f64 + 0.5) * dy;
            rhs[j * n + i] = (2.0 * std::f64::consts::PI * x).sin()
                * (2.0 * std::f64::consts::PI * y).sin();
        }
    }
    nullspace::subtract_mean(&mut rhs);
    PoissonCase { nx: n, ny: n, dx, dy, eta, rhs }
}

fn poisson_contrast(n: usize, seed: u64, contrast: f64) -> PoissonCase {
    use rand::{Rng, SeedableRng};
    use rand_chacha::ChaCha8Rng;
    let dx = 1.0 / n as f64;
    let dy = dx;
    let mut rng = ChaCha8Rng::seed_from_u64(seed);
    let log_c = contrast.ln();
    let eta: Vec<f64> = (0..n * n)
        .map(|_| {
            let u: f64 = rng.random::<f64>();
            (u * log_c).exp() // uniform in log-space so contrast is exactly `contrast`
        })
        .collect();
    let mut rhs = vec![0.0; n * n];
    let mut rng_r = ChaCha8Rng::seed_from_u64(seed.wrapping_add(17));
    for v in rhs.iter_mut() {
        let u: f64 = rng_r.random::<f64>();
        *v = u * 2.0 - 1.0; // uniform in [-1, 1]
    }
    nullspace::subtract_mean(&mut rhs);
    PoissonCase { nx: n, ny: n, dx, dy, eta, rhs }
}

/// Apply `A u` where `A = -∇·(η ∇u)` with periodic BCs, face η via
/// arithmetic mean.
fn apply_poisson(case: &PoissonCase, u: &[f64], out: &mut [f64]) {
    let nx = case.nx;
    let ny = case.ny;
    let inv_dx2 = 1.0 / (case.dx * case.dx);
    let inv_dy2 = 1.0 / (case.dy * case.dy);
    for j in 0..ny {
        let jp = (j + 1) % ny;
        let jm = (j + ny - 1) % ny;
        for i in 0..nx {
            let ip = (i + 1) % nx;
            let im = (i + nx - 1) % nx;
            let k = j * nx + i;
            let eta_c = case.eta[k];
            let eta_e = 0.5 * (eta_c + case.eta[j * nx + ip]);
            let eta_w = 0.5 * (eta_c + case.eta[j * nx + im]);
            let eta_n = 0.5 * (eta_c + case.eta[jp * nx + i]);
            let eta_s = 0.5 * (eta_c + case.eta[jm * nx + i]);
            let fx = (eta_e * (u[k] - u[j * nx + ip]) + eta_w * (u[k] - u[j * nx + im])) * inv_dx2;
            let fy = (eta_n * (u[k] - u[jp * nx + i]) + eta_s * (u[k] - u[jm * nx + i])) * inv_dy2;
            out[k] = fx + fy;
        }
    }
}

fn poisson_diag(case: &PoissonCase) -> Vec<f64> {
    let nx = case.nx;
    let ny = case.ny;
    let inv_dx2 = 1.0 / (case.dx * case.dx);
    let inv_dy2 = 1.0 / (case.dy * case.dy);
    let mut diag = vec![0.0; nx * ny];
    for j in 0..ny {
        let jp = (j + 1) % ny;
        let jm = (j + ny - 1) % ny;
        for i in 0..nx {
            let ip = (i + 1) % nx;
            let im = (i + nx - 1) % nx;
            let k = j * nx + i;
            let eta_c = case.eta[k];
            let eta_e = 0.5 * (eta_c + case.eta[j * nx + ip]);
            let eta_w = 0.5 * (eta_c + case.eta[j * nx + im]);
            let eta_n = 0.5 * (eta_c + case.eta[jp * nx + i]);
            let eta_s = 0.5 * (eta_c + case.eta[jm * nx + i]);
            diag[k] = (eta_e + eta_w) * inv_dx2 + (eta_n + eta_s) * inv_dy2;
        }
    }
    diag
}

/// Run one Jacobi-CG solve on the Poisson case; returns the solver
/// stats (iterations, converged flag).
fn solve_poisson_jacobi(case: &PoissonCase, tol: f64, max_iter: usize) -> SolverStats {
    let diag = poisson_diag(case);
    let cg = ConjugateGradient::new(tol, max_iter);
    let n = case.nx * case.ny;
    let mut x = vec![0.0; n];
    let b_scratch = case.rhs.clone();
    let mut matvec = |v: &[f64], out: &mut [f64]| apply_poisson(case, v, out);
    let mut precond = |r: &[f64], z: &mut [f64]| {
        for k in 0..n {
            z[k] = r[k] / diag[k].abs().max(1e-30);
        }
        // Scalar null-space: subtract mean, matching the velocity
        // Jacobi pattern in precond.rs where `project_velocity` wraps
        // the inverse-diagonal apply.
        nullspace::subtract_mean(z);
    };
    cg.solve(&mut matvec, &mut precond, &b_scratch, &mut x)
}

// ---------------------------------------------------------------------------
// Stokes snapshot cases
// ---------------------------------------------------------------------------

/// Pre-built state ready to be fed into a Jacobi-CG solve — avoids
/// rebuilding `TangentContext` and `VelocityJacobi` per criterion
/// sample.
struct StokesReplay {
    grid: StokesGrid,
    eta_center: Field2D,
    drag_diag: Option<Field2D>,
    ctx: TangentContext,
    vjac: VelocityJacobi,
    rhs_pack: Vec<f64>,
    cfg_tol: f64,
    cfg_max_iter: usize,
}

fn build_stokes_replay(snap: &LinearStokesSnapshot) -> StokesReplay {
    let grid = StokesGrid::new(snap.nx, snap.ny, snap.dx, snap.dy);
    let eta_center = field_from_vec(snap.eta_center.clone(), snap.nx, snap.ny);
    let drag_diag = snap
        .drag_diag
        .as_ref()
        .map(|v| field_from_vec(v.clone(), snap.nx, snap.ny));
    // Tangent context: reconstructed from stored per-cell fields. At
    // Newton outer iter 0 with initial v = 0, exx/eyy/exy are all
    // zero, so apply_tangent contributes nothing — but for captures
    // taken at later physics timesteps (where v_prev ≠ 0) the tangent
    // is non-trivial.
    let ctx = TangentContext {
        eta_center: eta_center.clone(),
        c_center: field_from_vec(
            snap.tangent_c_center.clone().unwrap_or_else(|| vec![0.0; snap.n_cells()]),
            snap.nx,
            snap.ny,
        ),
        exx_center: field_from_vec(
            snap.tangent_exx_center.clone().unwrap_or_else(|| vec![0.0; snap.n_cells()]),
            snap.nx,
            snap.ny,
        ),
        eyy_center: field_from_vec(
            snap.tangent_eyy_center.clone().unwrap_or_else(|| vec![0.0; snap.n_cells()]),
            snap.nx,
            snap.ny,
        ),
        exy_corner: field_from_vec(
            snap.tangent_exy_corner.clone().unwrap_or_else(|| vec![0.0; snap.n_cells()]),
            snap.nx,
            snap.ny,
        ),
    };
    let vjac = VelocityJacobi::from_diagonal(&snap.diag_vx, &snap.diag_vy, snap.diag_floor);
    let mut rhs_pack = Vec::with_capacity(2 * snap.n_cells());
    rhs_pack.extend_from_slice(&snap.rhs_vx);
    rhs_pack.extend_from_slice(&snap.rhs_vy);
    StokesReplay {
        grid,
        eta_center,
        drag_diag,
        ctx,
        vjac,
        rhs_pack,
        cfg_tol: snap.tol,
        cfg_max_iter: snap.max_iter,
    }
}

/// Run one Jacobi-CG solve on the Stokes replay; returns stats.
fn solve_stokes_jacobi(replay: &StokesReplay) -> SolverStats {
    let n = replay.grid.n_cells();
    let cg = ConjugateGradient::new(replay.cfg_tol, replay.cfg_max_iter);
    let mut x_pack = vec![0.0; 2 * n];
    let b_scratch = replay.rhs_pack.clone();
    let mut tmp_ax = vec![0.0; n];
    let mut tmp_ay = vec![0.0; n];
    let mut matvec = |v: &[f64], out: &mut [f64]| {
        let (vx_in, vy_in) = v.split_at(n);
        let (out_x, out_y) = out.split_at_mut(n);
        apply_momentum(
            &replay.grid,
            &replay.eta_center,
            replay.drag_diag.as_ref(),
            vx_in,
            vy_in,
            &mut tmp_ax,
            &mut tmp_ay,
        );
        out_x.copy_from_slice(&tmp_ax);
        out_y.copy_from_slice(&tmp_ay);
        apply_tangent(&replay.grid, &replay.ctx, vx_in, vy_in, out_x, out_y);
    };
    let mut precond = |r: &[f64], z: &mut [f64]| replay.vjac.apply(r, z);
    cg.solve(&mut matvec, &mut precond, &b_scratch, &mut x_pack)
}

// ---------------------------------------------------------------------------
// Criterion dispatch
// ---------------------------------------------------------------------------

fn bench_poisson(c: &mut Criterion, name: &str, case: PoissonCase) {
    // One warmup solve outside the timing loop to capture + log the
    // iteration count (deterministic, so one run suffices).
    let stats = solve_poisson_jacobi(&case, 1e-8, 4000);
    eprintln!(
        "[jacobi] {name:>24}  iters = {:4}  converged = {}  r_final = {:.3e}",
        stats.iterations,
        stats.converged(),
        stats.final_residual,
    );
    c.bench_function(name, |b| {
        b.iter_batched_ref(
            || (),
            |_| {
                let s = solve_poisson_jacobi(&case, 1e-8, 4000);
                criterion::black_box(s);
            },
            BatchSize::SmallInput,
        );
    });
}

fn bench_stokes(c: &mut Criterion, name: &str, snap: LinearStokesSnapshot) {
    let replay = build_stokes_replay(&snap);
    let stats = solve_stokes_jacobi(&replay);
    eprintln!(
        "[jacobi] {name:>24}  iters = {:4}  converged = {}  r_final = {:.3e}",
        stats.iterations,
        stats.converged(),
        stats.final_residual,
    );
    c.bench_function(name, |b| {
        b.iter_batched_ref(
            || (),
            |_| {
                let s = solve_stokes_jacobi(&replay);
                criterion::black_box(s);
            },
            BatchSize::SmallInput,
        );
    });
}

/// Resolve the `bench_data/` directory from the crate manifest so the
/// benchmark works regardless of whether `cargo bench` is invoked from
/// the workspace root or from inside the crate (cargo sets CWD to
/// the package dir, `bench_data/` lives at the workspace root).
fn bench_data_dir() -> PathBuf {
    let manifest_dir = std::env::var("CARGO_MANIFEST_DIR")
        .expect("CARGO_MANIFEST_DIR not set; run under cargo");
    PathBuf::from(manifest_dir).join("..").join("..").join("bench_data")
}

fn try_load_snapshot(case: &str) -> Option<LinearStokesSnapshot> {
    let path = bench_data_dir().join(format!("{}.bin", case));
    match LinearStokesSnapshot::load(&path) {
        Ok(s) => Some(s),
        Err(e) => {
            eprintln!("[skip] {}: {}", case, e);
            None
        }
    }
}

fn all_benches(c: &mut Criterion) {
    // --- Poisson synthetic ---
    bench_poisson(c, "poisson_constant", poisson_constant(64));
    bench_poisson(c, "poisson_contrast_100", poisson_contrast(64, 42, 100.0));
    bench_poisson(c, "poisson_contrast_10000", poisson_contrast(64, 42, 10000.0));

    // --- Stokes snapshots ---
    for case in &[
        "step0_quiescent",
        "step3_floor_yielding",
        "step6_voronoi",
        "step7_slab_off",
        "step8_activated",
        "step8_activated_128",
    ] {
        if let Some(snap) = try_load_snapshot(case) {
            bench_stokes(c, case, snap);
        }
    }
}

criterion_group!(benches, all_benches);
criterion_main!(benches);
